            if (out[i] > out[d] || (out[i] == out[d] && (p[i].votes < p[d].votes || (p[i].votes == p[d].votes && i > d)))) donor = static_cast<long>(i);
        }
        if (donor < 0) return;
        out[static_cast<size_t>(donor)]--;
        out[n] = 1;
    }
}

