#include "harness.hpp"
#include "seatshare.hpp"

using namespace seatshare;

int main() {
    h_init();
    std::vector<Party> parties = {{"Reeds", 340000}, {"Oaks", 280000}, {"Pines", 160000}, {"Ferns", 60000}};
    Options o;
    std::vector<int> r = allocate(parties, 7, o);
    CHECK_EQ(r.size(), 4u);
    int sum = 0;
    for (int x : r) sum += x;
    CHECK_EQ(sum, 7);
    CHECK_EQ(allocate(parties, 0, o)[0], 0);
    return h_report();
}
